    dependencies = ['official-map/mainline-shared-world-host-source-manifest.json',
                    'official-map/mainline-minimap-world-data-source-manifest.json',
                    'dungeons-runtime-source-manifest.json',
                    'daily-dungeon-achievements-source-manifest.json']
